// All names, ranks and points are sample data. Session changes are memory-only.
const community = { points:285, weekly:85, quizFinished:false, quizScore:0, taskFinished:false };
const members = [
  {name:'Eleanor Hughes',initials:'EH',role:'Mainframe architect',points:12480,change:2,tone:'ochre'},
  {name:'Robert Chen',initials:'RC',role:'COBOL specialist',points:11920,change:1,tone:'sage'},
  {name:'Patricia Williams',initials:'PW',role:'Systems engineer',points:10850,change:0,tone:'lilac'},
  {name:'James Mitchell',initials:'JM',role:'Banking systems expert',points:9640,change:3,tone:'blue'},
  {name:'Susan Park',initials:'SP',role:'Senior developer',points:9210,change:1,tone:'rose'},
  {name:'David Okafor',initials:'DO',role:'Application architect',points:8875,change:0,tone:'sage'},
  {name:'Margaret Evans',initials:'ME',role:'COBOL consultant',points:8340,change:2,tone:'ochre'}
];
const weeklyMembers = [members[4],members[1],members[0]];
const quizQuestions = [
  {question:'Which COBOL division defines the data items used by a program?',options:['IDENTIFICATION DIVISION','ENVIRONMENT DIVISION','DATA DIVISION','PROCEDURE DIVISION'],answer:2,explanation:'The DATA DIVISION describes the data items, including those in WORKING-STORAGE SECTION.'},
  {question:'What does PIC 9(5) describe?',options:['Five numeric digits','Five alphabetic characters','A number with five decimal places','A variable-length string'],answer:0,explanation:'9 is a numeric picture symbol. 9(5) repeats it five times, describing five numeric digit positions.'},
  {question:'Which statement repeats a paragraph until a condition is met?',options:['MOVE ... TO','DISPLAY ... UPON','ACCEPT ... FROM','PERFORM ... UNTIL'],answer:3,explanation:'PERFORM ... UNTIL repeats the specified procedure until the condition is true.'}
];
let quizSession={index:0,selected:null,checked:false,correct:0};
const starterCode = `       IDENTIFICATION DIVISION.
       PROGRAM-ID. DEPOSIT-DEMO.
       DATA DIVISION.
       WORKING-STORAGE SECTION.
       01 ACCOUNT-BALANCE PIC 9(5) VALUE 1000.
       01 DEPOSIT-AMOUNT  PIC 9(3) VALUE 250.
       PROCEDURE DIVISION.
           SUBTRACT DEPOSIT-AMOUNT FROM ACCOUNT-BALANCE
           DISPLAY ACCOUNT-BALANCE
           STOP RUN.`;
let taskDraft=starterCode;
function dashIcon(name){const paths={crown:'<path d="m3 6 4 4 5-7 5 7 4-4-2 13H5Z"/><path d="M6 16h12"/>',trophy:'<path d="M8 3h8v5a4 4 0 0 1-8 0V3Zm0 2H4v2a4 4 0 0 0 5 4m7-6h4v2a4 4 0 0 1-5 4m-3 1v6m-4 3h8m-7-3h6"/>',bolt:'<path d="m13 2-9 12h7l-1 8 10-13h-8Z"/>',book:'<path d="M12 5C8 2 3 3 3 3v16s5-1 9 2m0-16c4-3 9-2 9-2v16s-5-1-9 2V5Z"/>',user:'<circle cx="12" cy="8" r="4"/><path d="M4 22v-2a8 8 0 0 1 16 0v2"/>',clock:'<circle cx="12" cy="12" r="8.5"/><path d="M12 7.5V12l3 2"/>',wallet:'<path d="M4 7a2 2 0 0 1 2-2h11v4"/><rect x="4" y="7" width="16" height="12" rx="2"/><path d="M16 13h.01"/>'};return `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${paths[name]||icons[name]||icons.arrow}</svg>`;}
function userName(){return state.first ? `${state.first} ${state.last}`.trim() : 'Alex Morgan';}
function userInitials(){return userName().split(/\s+/).map(x=>x[0]).slice(0,2).join('').toUpperCase();}
function avatar(person,self=false){return `<span class="avatar ${self?'self':person.tone}" aria-hidden="true">${escapeHtml(self?userInitials():person.initials)}</span>`;}
function formatPoints(n){return n.toLocaleString('en-US');}
function dashboardView(){const remaining=Math.max(0,500-community.points);return `<div class="dashboard">
  <header class="dash-header"><a class="brand" href="#/" aria-label="HyperSquare home">${mark}HyperSquare</a><nav class="dash-nav" aria-label="Main navigation"><a href="#/" class="active" aria-current="page">Overview</a><a href="#/offers">Bank offers</a><a href="workspace/" target="_blank" rel="noopener">Expert workspace ${icon('up')}</a></nav><div class="dash-account"><span class="demo-label">Demo</span><button class="avatar-button" data-dashboard="profile" aria-label="Open your profile">${avatar({},true)}</button></div></header>
  <section class="dash-hero" aria-labelledby="hero-title">
    <div class="hero-text"><div class="eyebrow">THE HYPERSQUARE KNOWLEDGE PROGRAM</div><h1 id="hero-title">Preserve what COBOL experts know. <em>Help the next engineer.</em></h1><p>Experts answer short questions about their code. Once they confirm an answer, new engineers see it in their tickets.</p>
      <div class="hero-actions"><a class="hero-primary" href="workspace/" target="_blank" rel="noopener">Open Expert Workspace ${icon('up')}</a><button class="hero-secondary" data-scrollto="participate">What it takes ${icon('down')}</button></div></div>
    <aside class="example-card" aria-labelledby="example-title"><div class="example-head"><h2 id="example-title">How one answer helps</h2><span class="sample-chip">Sample scenario</span></div>
      <ol class="example-steps">
        <li><span class="ex-num">1</span><div><small>Expert answers</small><strong>Linda explains return code 4.</strong><q>“It just means something went to rejects.”</q></div></li>
        <li><span class="ex-num">2</span><div><small>Expert confirms</small><strong>She checks the AI draft and confirms it.</strong></div></li>
        <li><span class="ex-num">3</span><div><small>Engineer uses it</small><strong>Marcus sees it in ticket INC-2043 and fixes it at 2&nbsp;a.m.</strong></div></li>
      </ol></aside>
  </section>
  <section class="participate" id="participate" aria-labelledby="participate-title"><div class="section-head"><div><div class="eyebrow">WHAT IT TAKES · WHAT YOU GET</div><h2 id="participate-title">Short sessions. <em>Clear rewards.</em></h2></div><span class="sample-chip">Amounts are examples</span></div>
    <div class="give-get">
      <article><span class="gg-icon">${dashIcon('clock')}</span><h3>About 15 minutes</h3><p>3–5 questions per session. Pause anytime.</p></article>
      <article><span class="gg-icon">${dashIcon('wallet')}</span><h3>Paid per session</h3><p><b>Example:</b> $60 per confirmed session.</p></article>
      <article><span class="gg-icon">${dashIcon('sparkle')}</span><h3>Points unlock perks</h3><p><b>Example:</b> 50 points per answer. 500 unlocks bank offers.</p><a class="gg-link" href="#/offers">See sample offers ${icon('arrow')}</a></article>
      <article><span class="gg-icon">${icon('shield')}</span><h3>You stay in control</h3><p>Nothing is shared until you confirm it.</p></article>
    </div></section>
  <section class="community" aria-labelledby="community-title"><div class="section-head"><div><div class="eyebrow">COMMUNITY · OPTIONAL</div><h2 id="community-title">Leaderboard and practice</h2></div><p>Optional. Not needed to take part.</p></div>
  <div class="dashboard-grid">
    <section class="board-panel alltime-panel" aria-labelledby="alltime-title"><div class="panel-heading"><div><h2 id="alltime-title">Leaderboard ${dashIcon('crown')}</h2><p>Points from confirmed answers, not volume.</p></div><span class="board-tab">All time</span></div><div class="table-labels" aria-hidden="true"><span>#</span><span>Expert</span><span>Points</span><span>Change</span></div>
      <ol class="leader-list" aria-label="All-time sample rankings">${members.map((m,i)=>`<li class="leader-row"><span class="rank ${i<3?'top '+(i===1?'second':i===2?'third':''):''}" aria-label="Rank ${i+1}">${String(i+1).padStart(2,'0')}</span><div class="leader-person">${avatar(m)}<div class="person-text"><strong>${m.name}</strong><small>${m.role}</small></div></div><span class="leader-points">${formatPoints(m.points)}</span><span class="leader-change ${m.change?'':'neutral'}">${m.change?'↗ '+m.change:'—'}</span></li>`).join('')}</ol>
      <div class="you-row"><span class="rank">42</span><div class="leader-person">${avatar({},true)}<div class="person-text"><strong>${escapeHtml(userName())}<span class="you-tag">YOU</span></strong><small>Your story is just beginning.</small></div></div><span class="leader-points" id="your-board-points">${formatPoints(community.points)}</span><span class="leader-change">↗ 5</span></div>
    </section>
    <div class="right-stack"><section class="board-panel weekly-panel" aria-labelledby="weekly-title"><div class="panel-heading"><div><h2 id="weekly-title">This week’s leaders ${dashIcon('bolt')}</h2><p>A fresh chance to make your mark.</p></div><span class="week-chip">Weekly top 3</span></div><ol class="weekly-list" aria-label="Weekly sample rankings">${weeklyMembers.map((m,i)=>`<li><span class="rank">${i+1}</span>${avatar(m)}<div class="person-text"><strong>${m.name}</strong><small>${['On a roll','Going strong','Making moves'][i]}</small></div><span class="weekly-score">${[840,725,610][i]} <small>pts</small></span></li>`).join('')}</ol><p class="weekly-caption">Sample rankings · A new leaderboard every week</p></section>
    <section class="points-panel" aria-labelledby="your-points"><div class="points-heading" id="your-points">${dashIcon('sparkle')} Your points</div><div class="points-value"><strong>${formatPoints(community.points)}</strong><span>pts</span><small>+${community.weekly} this week</small></div><div class="points-progress"><div class="progress-copy"><strong>${remaining?remaining+' points until partner offers unlock':'Partner offers unlocked'}</strong><span>${Math.min(community.points,500)} / 500</span></div><div class="progress-track" role="progressbar" aria-label="Progress to 500 points" aria-valuemin="0" aria-valuemax="500" aria-valuenow="${Math.min(community.points,500)}"><div class="progress-fill" style="width:${Math.min(community.points/5,100)}%"></div></div><p class="points-note">Sample: 500 points unlocks the partner bank offers.</p></div></section></div>
  </div>
  <div class="dashboard-dock"><button class="quiz-cta" data-dashboard="quiz"><span class="quiz-symbol">${dashIcon('book')}</span><span class="quiz-copy"><small>OPTIONAL WARM-UP</small><strong>Weekly COBOL quiz</strong><p>${community.quizFinished?'Completed · See your result':'3 questions. A few minutes.'}</p></span><span class="quiz-reward">${community.quizFinished?'Completed':'+75 pts'}</span>${icon('arrow')}</button><button class="cobol-cta" data-dashboard="practice"><span><strong>COBOL NOW!</strong><small>${community.taskFinished?'Walkthrough complete · Review it':'Optional coding walkthrough'}</small></span>${icon('up')}</button></div>
  </section>
</div>`;}
function bindDashboard(){document.querySelectorAll('[data-dashboard]').forEach(b=>b.onclick=()=>({profile:openProfile,quiz:openQuiz,practice:openPractice}[b.dataset.dashboard])());document.querySelectorAll('[data-scrollto]').forEach(b=>b.onclick=()=>document.getElementById(b.dataset.scrollto)?.scrollIntoView({behavior:'smooth',block:'start'}));}
function dashboardDialog(html){dialog.classList.add('dashboard-modal');showDialog(html);}
function refreshDashboard(){if(document.body.classList.contains('dashboard-page')){app.innerHTML=dashboardView();bindDashboard();}}
function openProfile(){dashboardDialog(`<div class="eyebrow">YOUR EXPERT PROFILE</div><div class="profile-dialog-head">${avatar({},true)}<div><h2 id="dialog-title">${escapeHtml(userName())}</h2><p>${state.email?escapeHtml(state.email):'COBOL expert · Demo member'}</p></div></div><div class="profile-stats"><div><b>${community.points}</b><span>Total points</span></div><div><b>#42</b><span>Sample rank</span></div><div><b>${community.weekly}</b><span>This week</span></div></div><p>Your knowledge has a place here. Complete this week’s quiz or try the coding walkthrough to explore how contributions could earn points.</p><button class="primary-button" id="profile-quiz">Take the weekly quiz ${icon('arrow')}</button><p class="modal-footnote">Demo profile and sample rankings. Progress stays in this page until refresh; no information or recordings are submitted.</p>`);document.querySelector('#profile-quiz').onclick=openQuiz;}
function openQuiz(){if(community.quizFinished){renderQuizResult(true);return;}quizSession={index:0,selected:null,checked:false,correct:0};renderQuiz();}
function renderQuiz(){const q=quizQuestions[quizSession.index];dashboardDialog(`<div class="eyebrow">WEEKLY COBOL QUIZ · ${quizSession.index+1} OF 3</div><h2 id="dialog-title">Keep your edge.</h2><div class="quiz-progress" aria-hidden="true">${quizQuestions.map((_,i)=>`<span class="${i<=quizSession.index?'done':''}"></span>`).join('')}</div><p class="quiz-question">${q.question}</p><div class="quiz-options" role="group" aria-label="Choose your answer">${q.options.map((v,i)=>`<button class="quiz-option ${quizSession.selected===i?'selected':''}" aria-pressed="${quizSession.selected===i}" data-answer="${i}" ${quizSession.checked?'disabled':''}><span>${'ABCD'[i]}</span>${v}</button>`).join('')}</div>${quizSession.checked?`<div class="quiz-feedback ${quizSession.selected===q.answer?'':'wrong'}" role="status"><b>${quizSession.selected===q.answer?'That’s right.':'Not quite.'}</b> ${q.explanation}</div>`:''}<button class="primary-button" id="quiz-next" ${quizSession.selected===null?'disabled':''}>${quizSession.checked?(quizSession.index===2?'See my results':'Next question'):'Check answer'} ${icon('arrow')}</button><p class="modal-footnote">25 demo points per correct answer. One scored attempt per page session.</p>`);document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{quizSession.selected=Number(b.dataset.answer);renderQuiz();});document.querySelector('#quiz-next').onclick=()=>{if(!quizSession.checked){quizSession.checked=true;if(quizSession.selected===q.answer)quizSession.correct++;renderQuiz();}else if(quizSession.index<2){quizSession.index++;quizSession.selected=null;quizSession.checked=false;renderQuiz();}else{community.quizFinished=true;community.quizScore=quizSession.correct;community.points+=quizSession.correct*25;community.weekly+=quizSession.correct*25;refreshDashboard();renderQuizResult(false);}};}
function renderQuizResult(previous){dashboardDialog(`<div class="quiz-result">${dashIcon('trophy')}<div class="eyebrow">WEEKLY QUIZ COMPLETE</div><h2 id="dialog-title">${community.quizScore===3?'You know your COBOL.':'Another step forward.'}</h2><strong>${community.quizScore} / 3</strong><p>${previous?'Your saved result for this page session.':'Nice work making time for your craft.'}<br>${community.quizScore*25} demo points earned.</p><button class="primary-button" id="quiz-done">Back to overview ${icon('arrow')}</button><p class="modal-footnote">Points are awarded once per page session and reset on refresh.</p></div>`);document.querySelector('#quiz-done').onclick=()=>dialog.close();}
function openPractice(){dashboardDialog(`<div class="eyebrow">COBOL NOW · SAMPLE WALKTHROUGH</div><h2 id="dialog-title">A deposit should add up.</h2><p>This sample account starts at 1,000. A deposit of 250 should produce <b>01250</b>. Fix the arithmetic statement, then check your solution.</p><label class="task-label" for="task-code">DEPOSIT-DEMO.cbl</label><textarea class="task-code" id="task-code" spellcheck="false" autocapitalize="off" aria-describedby="task-scope">${escapeHtml(taskDraft)}</textarea><button class="task-hint" id="task-hint">Show a hint</button><div class="task-feedback" id="task-feedback" role="status">${community.taskFinished?'Completed · 75 demo points already earned.':''}</div><button class="primary-button" id="task-check">Check solution ${icon('arrow')}</button><p class="modal-footnote" id="task-scope">Guided pattern check, not a COBOL compiler. No screen recording takes place. Use this sample code only. Earn 75 demo points once per page session.</p>`);document.querySelector('#task-code').oninput=e=>{taskDraft=e.target.value;};document.querySelector('#task-hint').onclick=()=>{document.querySelector('#task-feedback').textContent='Use ADD DEPOSIT-AMOUNT TO ACCOUNT-BALANCE in place of the SUBTRACT statement.';};document.querySelector('#task-check').onclick=()=>{const code=taskDraft.toUpperCase().split('\n').filter(line=>line[6]!=='*').join('\n');const correct=/\bADD\s+DEPOSIT-AMOUNT\s+TO\s+ACCOUNT-BALANCE\b/.test(code)&&! /\bSUBTRACT\s+DEPOSIT-AMOUNT\s+FROM\s+ACCOUNT-BALANCE\b/.test(code);if(correct){const already=community.taskFinished;if(!already){community.taskFinished=true;community.points+=75;community.weekly+=75;refreshDashboard();}document.querySelector('#task-feedback').textContent=already?'Correct pattern. You already earned points for this walkthrough.':'Correct arithmetic pattern! With the sample inputs, the balance is 01250. You earned 75 demo points.';document.querySelector('#task-check').textContent='Back to overview';document.querySelector('#task-check').onclick=()=>dialog.close();}else document.querySelector('#task-feedback').textContent='Look at the arithmetic statement: a deposit increases the balance. Replace SUBTRACT ... FROM with ADD ... TO, then try again.';};}
